action.command:
cd /workspace && docker compose exec -T backend node -e '
(async () => {
  const r = await fetch("http://backend:4000/api/v1/swagger.json");
  const j = await r.json();
  const p = j.paths["/auth/init-email-login"] || Object.keys(j.paths).find(k=>k.includes("init-email"));
  console.log("path:", p);
  console.log(JSON.stringify(j.paths[p], null, 1).slice(0, 2500));
})();
' 2>&1 | head -60

